CREATE OR REPLACE FUNCTION public.bairros_log()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
BEGIN

   IF (TG_OP IN ('UPDATE','DELETE'))
   THEN 
		INSERT INTO bairros_Log (estado,cidade,codigo,nome,cep,
								Trigger_Mode, Trigger_Tuple, Trigger_Changed, Trigger_User)
                    
        VALUES ( OLD.estado,OLD.cidade,OLD.codigo,OLD.nome,OLD.cep, 
				 TG_OP, 'OLD', NOW(), CURRENT_USER);
				 
		IF(TG_OP='DELETE') THEN 
			RETURN OLD; 
		END IF;
						  
	END IF;

	IF (TG_OP IN ('INSERT','UPDATE')) 
	THEN
			INSERT INTO bairros_Log (estado,cidade,codigo,nome,cep,
					  Trigger_Mode, Trigger_Tuple, Trigger_Changed, Trigger_User)
                    
               VALUES ( NEW.estado,NEW.cidade,NEW.codigo,NEW.nome,NEW.cep,
						  TG_OP, 'NEW', NOW(), CURRENT_USER);
        RETURN NEW;		
    END IF;  
END;
$function$

