CREATE OR REPLACE FUNCTION public.contratos_antesinserir()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
     vRenegociado  BOOLEAN;
 begin
   IF (TG_OP = 'INSERT') THEN
   
      /*PARA VENDAS DO SITE*/
      IF (COALESCE(NEW.desconto,0)>0) and 
         (COALESCE(NEW.descontofinanceiro,0)+COALESCE(NEW.descontogeral,0)=0) AND
         exists (select contrato from pedidos_site p_s where p_s.contrato = new.numero) THEN
         NEW.descontofinanceiro=NEW.desconto;
      END IF;

     IF NEW.origem IS NOT NULL THEN
        SELECT origem IS NOT NULL INTO vRenegociado
           FROM contratos
           WHERE contratos.origem = NEW.origem;
        
        IF (vRenegociado IS NOT NULL) AND vRenegociado THEN
           RAISE EXCEPTION 'Renegocia��o n�o permitida para o contrato (%) renegociado',NEW.origem;
        END IF;
        
     END IF;
    
     IF new.numero is null then
       new.numero := contratos_proximonumero();
     END IF;
    
   ELSE
     IF (TG_OP = 'UPDATE') THEN
           
       IF ((NEW.situacao = 'R') AND ((OLD.situacao IN ('F','N','P','C')) AND (COALESCE(NEW.OPERACAO,'')<>'C'))) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;         
       ELSEIF ((NEW.situacao = 'O') AND ((OLD.situacao IN ('R','F','N','P','C')) AND (COALESCE(NEW.OPERACAO,'')<>'C'))) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;        
       ELSEIF OLD.SITUACAO='N' AND NEW.SITUACAO IN ('F','P') AND not produtos_pendentes(new.numero) THEN
         RAISE EXCEPTION 'Problemas na atualiza��o do contrato "%", Sit. anterior: "%" atual: "%". Entre em contato com o suporte!',new.numero,old.situacao,new.situacao;        
       ELSEIF ((NEW.situacao = 'R') AND (OLD.situacao = 'O')) THEN
         if NEW.datareservado is null then
           NEW.datareservado = current_date;
         end if;
       ELSEIF ((NEW.situacao='R') AND (OLD.situacao IN ('F','N','P') AND (COALESCE(NEW.OPERACAO,'')='C'))) THEN
         NEW.faturamento=NULL;
         NEW.operacao=NULL;
       ELSEIF ((NEW.situacao='F' OR NEW.situacao='N' OR NEW.situacao='P') AND OLD.situacao IN ('O','R') AND (NEW.faturamento IS NULL)) THEN
         if NEW.faturamento is null then
           NEW.faturamento = current_date;
         end if;  
         /*
       ELSEIF NEW.situacao='C' THEN  
         update atendimentos set status = 'F' where contrato = new.numero and exists (select ap.atendimento from atendimentosprodutos ap where ap.atendimento = atendimentos.codigo);
        */ 
       END IF;
       
       NEW.operacao=NULL;
    
     END IF;
    
   END IF;

   IF TG_OP='UPDATE' THEN
       IF ((NEW.SITUACAO IN ('N','P')) OR (OLD.SITUACAO<>'R' AND NEW.SITUACAO='F'))
          and coalesce(new.creditotroca,0) <> 0
          and exists (select p.contrato
                      from parcelas p
                      where p.contrato = new.numero
                        and p.formapagamento = 'T'
                        and (p.datapagto is null or coalesce(p.valorpagto,0)=0) limit 1)
        THEN
            RAISE EXCEPTION 'O contrato % possui parcelas com pagamento em cr�dito de troca sem data ou valor de pagamento. Entre em contato com o suporte da tecSOFT.', new.numero;    
        END IF;                 
        
    END IF;
    
    RETURN NEW;
    
 end;
$function$

CREATE OR REPLACE FUNCTION public.trg_limpar_emitirnotadepoisde()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- S� processa se tiver valor
    IF NEW.emitirnotadepoisde IS NOT NULL THEN
        
        -- Compara o ano da data com o ano atual
        IF EXTRACT(YEAR FROM NEW.emitirnotadepoisde) < EXTRACT(YEAR FROM CURRENT_DATE) THEN
            NEW.emitirnotadepoisde := NULL;
        END IF;

    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dadosfiscais_antesatualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
r_cliente record;
v_numerodadofiscal INTEGER;
BEGIN

   IF TG_OP='INSERT' THEN	
   
     IF NEW.Numero IS NULL THEN 
       NEW.Numero:= DadosFiscais_ProximoNumero();
     END IF;
	 
   end if;	 
	
    if new.chv_nfe is not null and new.numero is not null THEN 	 
	
	   select df.numero into v_numerodadofiscal
	   FROM dadosfiscais df 
	   where df.numero <> new.numero 
	     and df.chv_nfe = new.chv_nfe;	 
	   
	   if found then
	     RAISE EXCEPTION 'Existe outro documento fiscal de n�mero % como com a mesma chave % que sendo atualizada. Entre em contato com o suporte!', v_numerodadofiscal, new.chv_nfe;
	   end if;
		 
	end if;  
   
	IF (NEW.situacao='C' and NEW.datacancelamento IS NULL) THEN
		NEW.datacancelamento=CURRENT_DATE;
	END IF;
		
	IF TG_OP='UPDATE' THEN
	
		IF NEW.pessoatipo IS NULL OR NEW.pessoatipo='' THEN
			NEW.pessoatipo='F';
		END IF;
		
		IF (NEW.estadocfo='' OR NEW.estadocfo is null) THEN
			NEW.estadocfo=(SELECT estado FROM filiais where codigo=NEW.filialvenda);
		END IF;
		
		IF (NEW.cliente <> OLD.cliente) THEN	
			SELECT vf.*,c.codigoibge,c.nome as nomecidade,b.nome as nomebairro
			FROM vfornecedores vf,cidades c,bairros b
			WHERE vf.codigo=NEW.cliente 
			AND vf.tipo=NEW.tipocliente 
			AND vf.cidade=c.codigo
			AND vf.estado=c.estado
			AND vf.cidade=b.cidade
			AND vf.bairro=b.codigo
			AND vf.estado=b.estado
			INTO r_cliente;
			
			IF FOUND THEN
				NEW.rua=r_cliente.rua;
				NEW.cidade=r_cliente.cidade;
				NEW.bairro=r_cliente.bairro;
				NEW.cep=r_cliente.cep;
				NEW.cidadeibge=r_cliente.codigoibge;
				NEW.nomecidade=r_cliente.nomecidade;
				NEW.nomebairro=r_cliente.nomebairro;
				NEW.estado=r_cliente.estado;
				NEW.endnumero=r_cliente.numero;
				NEW.endcomplemento=r_cliente.complemento;
			END IF;
		END IF;
	END IF;
   RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dadosfiscais_antesinserir()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
ventcep_contrato INTEGER;
BEGIN
   IF NEW.Numero IS NULL THEN 
     NEW.Numero:= DadosFiscais_ProximoNumero();
   END IF;


	IF NEW.IndPres IS NULL THEN 
		NEW.IndPres := 0;
    END IF;
	
	IF NEW.ClienteContribICMS IS NULL THEN----------------------- Como � NOT NULL, nas ECFs pode dar erro
		NEW.ClienteContribICMS = FALSE;   
	END IF;

   IF NEW.Conceito IS NULL AND NEW.TipoCliente='C' THEN
		NEW.Conceito=(SELECT conceito FROM clientes WHERE codigo=NEW.cliente);
   END IF;
   
   IF (NEW.contrato IS NOT NULL AND new.localentrega_cep IS NULL) THEN
		ventcep_contrato:=(select entcep from contratos where contratos.numero=new.contrato);
		IF (NEW.localentrega_cep IS NULL AND ventcep_contrato is not null) THEN
			NEW.localentrega_cep:=ventcep_contrato;
		END IF;
   END IF;
   
   RETURN NEW;

END;
$function$

CREATE OR REPLACE FUNCTION public.dadosfiscais_depoisatualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE
   vPedidoFilial RECORD;
   vEmEstoque   NUMERIC(11,3);
   vQuantidadeMovimentada NUMERIC(11,3);
 begin
      --SE ESTIVER CANCELANDO UMA NOTA FISCAL DE TRANSFERENCIA, REABRE A REQUISI��O.
      IF NEW.situacao='C' AND OLD.situacao<>'C'  THEN
        
		 IF NEW.contrato IS NOT NULL THEN
			UPDATE pedidos_site SET marketplace_chave_nfe=false WHERE contrato=NEW.contrato;
		 END IF;
		
		 IF ((NEW.codigofiscal%1000 IN (150,151,152,155,156,408,409,552,557)) OR (ehnotafiscalsaidavenda(NEW.codigofiscal) AND NEW.tipocliente='L')) THEN 
			 FOR vPedidoFilial IN SELECT * FROM PedidosFiliais WHERE PedidosFiliais.dadofiscal = New.Numero 
			 LOOP
				--CASO A QUANTIDADE CONFIRMADA SEJA MENOR QUE A PEDIDA, ADICIONA NOVAMENTE EM RESERVA PREVIA A DIFERENCA
				IF (vPedidoFilial.QtdePedida>vPedidoFilial.QtdeRecebida) AND (parametros_valor('REQUISICAOSUBTRAIESTOQUE')='True') THEN
					
					--a quantidade movimentada nesta operacao nao podera ser maior que do a quantidade em estoque (15/05/2015)
					vEmestoque:=(select emestoque from estoques where produto=vPedidoFilial.produto and filial=vPedidoFilial.requisitada);
					IF vEmEstoque>=(VPedidoFilial.QtdePedida-VPedidoFilial.QtdeRecebida) THEN
						vQuantidadeMovimentada:=VPedidoFilial.QtdePedida-VPedidoFilial.QtdeRecebida;
					ELSE
						vQuantidadeMovimentada:=vEmEstoque;
						UPDATE pedidosfiliais SET qtdepedida=vQuantidadeMovimentada+vPedidoFilial.qtderecebida WHERE codigo=VPedidoFilial.codigo;
					END IF;
					INSERT INTO movimentos (produto,filial,quantidade,tipomovimento,referencia) 
								  VALUES (VPedidoFilial.produto,VPedidoFilial.Requisitada,
									 vQuantidadeMovimentada,
								  'TEP','REQUISI��O '||CAST(vPedidoFilial.codigo AS VARCHAR) ||' REABERTURA ');
				END IF;
			 END LOOP;
			
			 UPDATE pedidosfiliais SET situacao='A',dadofiscal=null WHERE pedidosfiliais.dadofiscal=NEW.numero;
		 END IF;
      END IF;
      RETURN NEW;
 end;$function$

CREATE OR REPLACE FUNCTION public.dadosfiscais_incluirromaneio()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  vEntreFiliais Boolean;
  vRomaneio integer;
  vSituacao varchar;
BEGIN
         
  if (tg_op = 'UPDATE') and coalesce(new.modoinclusaoromaneio,0) <> 0
                        and coalesce(old.modoinclusaoromaneio,0) = 0 then
                        
     perform incluir_romaneio (new.Cliente, new.TipoCliente, new.numero, new.FilialEmissao, new.modoinclusaoromaneio);
     
  else
    if (tg_op = 'UPDATE' and new.situacao = 'C' and old.situacao <> 'C') then
     
      select rn.romaneio
      from romaneiosnotas rn
      where rn.dadofiscal = new.numero 
      order  by rn.romaneio desc limit 1 into vRomaneio;
     
      if found then
        select atualizar_situacao_romaneio(vRomaneio) into vSituacao;
      end if;  
     
    end if;
  end if;
  
  
  
   RETURN NEW;
  
END;
$function$

