CREATE OR REPLACE FUNCTION public.produtos_audit_log_fn()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  ign CONSTANT text[] := ARRAY[
    'created_at', 'updated_at', 'cloud_row_version'
  ];
  r record;
  diff jsonb := '{}'::jsonb;
  o_txt text;
  n_txt text;
  app_uid_text text;
  app_uid bigint;
  app_login text;
  app_name text;
  app_src text;
  app_req text;
  db_user text;
  filial_ref integer;
  pe_old numeric;
  pe_new numeric;
BEGIN
  db_user := CURRENT_USER::text;

  BEGIN
    filial_ref := NULLIF(btrim(current_setting('app.filial_codigo', true)), '')::integer;
  EXCEPTION WHEN OTHERS THEN
    filial_ref := NULL;
  END;

  BEGIN
    app_uid_text := current_setting('app.user_id', true);
  EXCEPTION WHEN OTHERS THEN
    app_uid_text := '';
  END;
  IF app_uid_text IS NULL OR btrim(app_uid_text) = '' THEN
    app_uid := NULL;
  ELSE
    BEGIN
      app_uid := app_uid_text::bigint;
    EXCEPTION WHEN OTHERS THEN
      app_uid := NULL;
    END;
  END IF;

  BEGIN
    app_login := NULLIF(btrim(current_setting('app.user_login', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_login := NULL;
  END;
  BEGIN
    app_name := NULLIF(btrim(current_setting('app.user_name', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_name := NULL;
  END;
  BEGIN
    app_src := NULLIF(btrim(current_setting('app.source', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_src := NULL;
  END;
  BEGIN
    app_req := NULLIF(btrim(current_setting('app.request_id', true)), '');
  EXCEPTION WHEN OTHERS THEN
    app_req := NULL;
  END;

  IF TG_OP = 'INSERT' THEN
    pe_new := NULL;
    IF filial_ref IS NOT NULL THEN
      BEGIN
        SELECT estoques_preco(NEW.codigo, filial_ref, 0::numeric) INTO pe_new;
      EXCEPTION WHEN OTHERS THEN
        pe_new := NULL;
      END;
    END IF;

    INSERT INTO public.produtos_log_new (
      produto_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id,
      filial_codigo_ref, preco_efetivo_ant, preco_efetivo_novo, preco_final_mudou, dados
    ) VALUES (
      NEW.codigo, 'INSERT', 'new', db_user,
      app_uid, app_login, app_name, app_src, app_req,
      filial_ref, NULL, pe_new, NULL, row_to_json(NEW)::jsonb
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    pe_old := NULL;
    IF filial_ref IS NOT NULL THEN
      BEGIN
        SELECT estoques_preco(OLD.codigo, filial_ref, 0::numeric) INTO pe_old;
      EXCEPTION WHEN OTHERS THEN
        pe_old := NULL;
      END;
    END IF;

    INSERT INTO public.produtos_log_new (
      produto_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id,
      filial_codigo_ref, preco_efetivo_ant, preco_efetivo_novo, preco_final_mudou, dados
    ) VALUES (
      OLD.codigo, 'DELETE', 'old', db_user,
      app_uid, app_login, app_name, app_src, app_req,
      filial_ref, pe_old, NULL, NULL, row_to_json(OLD)::jsonb
    );
    RETURN OLD;
  END IF;

  FOR r IN
    SELECT a.attname AS col
    FROM pg_attribute a
    WHERE a.attrelid = 'public.produtos'::regclass
      AND a.attnum > 0
      AND NOT a.attisdropped
  LOOP
    IF r.col = ANY (ign) THEN
      CONTINUE;
    END IF;
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', r.col, r.col) USING OLD, NEW INTO o_txt, n_txt;
    IF o_txt IS DISTINCT FROM n_txt THEN
      diff := diff || jsonb_build_object(
        r.col,
        jsonb_build_object('old', to_jsonb(o_txt), 'new', to_jsonb(n_txt))
      );
    END IF;
  END LOOP;

  pe_old := NULL;
  pe_new := NULL;
  IF filial_ref IS NOT NULL THEN
    BEGIN
      SELECT estoques_preco(OLD.codigo, filial_ref, 0::numeric) INTO pe_old;
    EXCEPTION WHEN OTHERS THEN
      pe_old := NULL;
    END;
    BEGIN
      SELECT estoques_preco(NEW.codigo, filial_ref, 0::numeric) INTO pe_new;
    EXCEPTION WHEN OTHERS THEN
      pe_new := NULL;
    END;
  END IF;

  IF diff <> '{}'::jsonb OR (pe_old IS DISTINCT FROM pe_new) THEN
    INSERT INTO public.produtos_log_new (
      produto_codigo, trigger_mode, trigger_tuple, trigger_user_db,
      app_user_id, app_user_login, app_user_name, app_source, request_id,
      filial_codigo_ref, preco_efetivo_ant, preco_efetivo_novo, preco_final_mudou, dados
    ) VALUES (
      NEW.codigo, 'UPDATE', 'diff', db_user,
      app_uid, app_login, app_name, app_src, app_req,
      filial_ref, pe_old, pe_new,
      (pe_old IS DISTINCT FROM pe_new),
      CASE WHEN diff <> '{}'::jsonb THEN diff ELSE '{}'::jsonb END
    );
  END IF;

  RETURN NEW;
END;
$function$

