                  IF NOT EXISTS (SELECT CodigoBarras
                                    FROM ProdutosCodigoBarras
                                    WHERE CodigoBarras = vCodBarras)
                  THEN INSERT INTO ProdutosCodigoBarras (Produto, CodigoBarras)
                              VALUES (NEW.Codigo, vCodBarras);
                  END IF;
            END IF;
        END IF;
   END IF;

   RETURN NEW;

END;
$function$

CREATE OR REPLACE FUNCTION public.produtos_fill_derived_cols()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    /* Always recompute on INSERT � */
    IF (TG_OP = 'INSERT') THEN
        NEW.descricao_complementar_text := strip_html_tags(NEW.descricaocomplementar);
        NEW.caracteristicas_text        := strip_html_tags(NEW.caracteristicas);
        RETURN NEW;
    END IF;

    /* � or on UPDATE only when the source columns actually changed.    */
    IF (NEW.descricaocomplementar IS DISTINCT FROM OLD.descricaocomplementar) THEN
        NEW.descricao_complementar_text := strip_html_tags(NEW.descricaocomplementar);
    END IF;

    IF (NEW.caracteristicas IS DISTINCT FROM OLD.caracteristicas) THEN
        NEW.caracteristicas_text := strip_html_tags(NEW.caracteristicas);
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.produtoscontratos_antesinserir()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    orcamento_codigo INTEGER;
	r_produto_orcamento RECORD;
BEGIN
    -- Obt�m o c�digo do orcamento vinculado ao contrato
    SELECT codigo INTO orcamento_codigo FROM orcamentos WHERE contrato = NEW.contrato;
	
	-- Verifica se h� um orcamento vinculado ao contrato
	IF orcamento_codigo IS NOT NULL THEN
		SELECT * FROM produtosorcamentos INTO r_produto_orcamento where orcamento=orcamento_codigo AND produto=NEW.produto;
		IF FOUND THEN    
			-- Atualiza os campos de entrega com base no orcamento
			SELECT dataentrega, horaentrega, periodoentrega, COALESCE(NULLIF(entrega,''),'N') 
			INTO NEW.dataentrega, NEW.horaentrega, NEW.periodoentrega,new.entrega 
			FROM produtosorcamentos 
			WHERE orcamento = orcamento_codigo AND produto = NEW.produto;
		END IF;
	END IF;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.produtoscontratos_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  vProdutos RECORD;
BEGIN
  IF TG_OP='INSERT'  THEN
    new.setorvenda := (select u.setorvenda from usuarios u where u.codigo = new.vendedor);
	/*PARA VENDAS DO SITE*/
	  IF (COALESCE(NEW.desconto,0)>0) and (COALESCE(NEW.descontofinanceiro,0)+COALESCE(NEW.descontogeral,0)=0) THEN
		 NEW.descontofinanceiro=NEW.desconto;
	  END IF;
	  
	  IF (NEW.entrega='S') AND (NEW.dataentrega IS NULL) THEN
		 NEW.dataentrega=current_Date;
		 NEW.horaentrega='08:00:00';
		 NEW.periodoentrega=1;
	  END IF;
  ELSE 
    IF TG_OP='UPDATE' AND NEW.vendedor <> OLD.vendedor THEN
        new.setorvenda := (select u.setorvenda from usuarios u where u.codigo = new.vendedor);
    END IF;
  END IF;
  
  select p.caracteristica, p.preco, p.promocao, pro.descricao as descricaopromocao into vProdutos
  from produtos p 
       left join promocoes pro 
       on p.promocao = pro.codigo
  where p.codigo = new.produto;     
  
  new.caracteristica := vprodutos.caracteristica;
  new.preco := vprodutos.preco;
  new.codigopromocao := vprodutos.promocao;
  new.descricaopromocao := vprodutos.descricaopromocao;
  
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.produtoscontratos_depoisinseriratualizarapagar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_orc_codigo       varchar(20);
  v_tem_orc          boolean;
  v_tem_ctr          boolean;
  v_ult_alt_orc      timestamp;
BEGIN
  /* -------------------- REGRAS EXISTENTES -------------------- */
  IF TG_OP = 'UPDATE' THEN
    IF ((select count(*) from parametrosfiliais where parametro = 189 and valor = 'True') > 0) THEN -- se utilizar fidelidade
      IF ((NEW.cancelado > OLD.cancelado) OR (NEW.cancelado > 0 AND OLD.cancelado IS NULL))
         AND (NEW.cancelado < NEW.quantidade) THEN
        PERFORM produtoscontratos_atualizarbonus(NEW.contrato, NEW.produto, NEW.quantidade, NEW.cancelado);
      END IF;
    END IF;
  END IF;

  IF TG_OP IN ('INSERT','UPDATE') THEN
    IF (parametros_valor('Pre�o para clientes') = 'True') THEN -- se utilizar Pre�o para clientes
      PERFORM contratos_atualizarclientesprodutos(NEW.contrato, NEW.produto, NEW.precovenda);
    END IF;
  END IF;

  IF (TG_OP = 'DELETE') OR (TG_OP = 'UPDATE') THEN
    IF (TG_OP = 'DELETE')
       OR (TG_OP = 'UPDATE' AND (OLD.produto <> NEW.produto OR OLD.contrato <> NEW.contrato)) THEN
      DELETE FROM produtosconferencia
       WHERE tipo   = 'CTR'
         AND codigo = CAST(OLD.contrato AS varchar)
         AND produto = OLD.produto;
    END IF;
  END IF;

  --raise notice 'aqui';
  /* -------------------- NOVO: C�PIA ORC -> CTR PRODUTOSCONFERIDOS JR 24/09/2025-------------------- */
  IF TG_OP IN ('INSERT') THEN
	 
	--RAISE NOTICE 'INSERINDO';
    -- S� tenta copiar quando h� um contrato definido
    IF NEW.contrato IS NOT NULL THEN

      -- J� existe produtosconferencia para este contrato (CTR)? Evita duplicar c�pias.
      SELECT EXISTS (
               SELECT 1 FROM produtosconferencia
                WHERE tipo='CTR' AND codigo = CAST(NEW.contrato AS varchar)
				AND produto=new.produto
             )
        INTO v_tem_ctr;
	  --RAISE NOTICE 'TEM CONTRATO %',v_tem_ctr;
	  
      IF NOT v_tem_ctr THEN
        -- Encontrar o or�amento ligado a este contrato e obter o "codigo" que foi usado na conferencia ORC.
        -- Ajuste aqui se o "codigo" da conferencia ORC for outro atributo.
        SELECT o.codigo::varchar
          FROM orcamentos o
         WHERE o.contrato = NEW.contrato
         LIMIT 1
         INTO v_orc_codigo;
		 
		 --RAISE NOTICE 'ORCAMENTO %',v_orc_codigo;

        IF v_orc_codigo IS NOT NULL THEN
          -- Existe conferencia ORC para esse or�amento?
          SELECT EXISTS (
                   SELECT 1 FROM conferencia c
                    WHERE c.tipo='ORC' AND c.codigo = v_orc_codigo
                 )
            INTO v_tem_orc;

          IF v_tem_orc THEN
            -- �ltima altera��o dos itens do ORC
            SELECT MAX(pc.datahora_alteracao)
              FROM produtosconferencia pc
             WHERE pc.tipo='ORC' AND pc.codigo = v_orc_codigo
             INTO v_ult_alt_orc;
			 
			 --RAISE NOTICE 'ULTIM ALT, %',v_ult_alt_orc;

            -- S� copia se a confer�ncia do or�amento N�O for mais antiga que 2 dias
			--RAISE NOTICE 'VERIFICANDO DATA';
            IF v_ult_alt_orc IS NULL OR (now() - v_ult_alt_orc) <= INTERVAL '2 days' THEN
			  --RAISE NOTICE 'PASSOU INTERVALO';
              -- Copia a "cabe�a" da conferencia: ORC -> CTR (se ainda n�o existir)
              INSERT INTO conferencia (tipo, codigo, data, usuario, filial)
              SELECT 'CTR', CAST(NEW.contrato AS varchar), c.data, c.usuario, c.filial
                FROM conferencia c
               WHERE c.tipo='ORC' AND c.codigo = v_orc_codigo
                 AND NOT EXISTS (
                       SELECT 1 FROM conferencia c2
                        WHERE c2.tipo='CTR' AND c2.codigo = CAST(NEW.contrato AS varchar)
                 )
              ;

              -- Copia os itens de produtosconferencia: ORC -> CTR
              INSERT INTO produtosconferencia
                  (tipo, codigo, produto, lido, digitado, datahora_inclusao, datahora_alteracao, numero)
              SELECT
                  'CTR',
                  CAST(NEW.contrato AS varchar),
                  pc.produto,
                  pc.lido,
                  pc.digitado,
                  now(),
                  now(),
                  pc.numero
              FROM produtosconferencia pc
              WHERE pc.tipo='ORC' AND pc.codigo = v_orc_codigo
              ON CONFLICT (tipo, codigo, produto, numero) DO NOTHING;

            END IF; -- janela de 2 dias
          END IF; -- existe ORC
        END IF; -- tem orcamento associado
      END IF; -- j� existia CTR
    END IF; -- NEW.contrato not null
  END IF;

  /* -------------------- RETORNO PADR�O -------------------- */
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.produtosdadosfiscais_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  vProdutos RECORD;

BEGIN
  new.ind_mov_fisica := (select ind_mov_fisica
                          from naturezas
                          where codigo = new.natureza);            
                          
  if NULLIF(new.montagem,'') is null then
    new.montagem := 'N';
  end if;
  
  if NULLIF(new.entrega,'') is null then
    new.entrega := 'N';
  end if;  
 
  if new.qtdeestoque is null then
    new.qtdeestoque := new.quantidade;
  end if;

  if new.fatorconversao is null then
     new.fatorconversao := 1;
  end if;
   
  select p.caracteristica, p.preco, p.promocao, pro.descricao as descricaopromocao into vProdutos
  from produtos p 
       left join promocoes pro 
       on p.promocao = pro.codigo
  where p.codigo = new.produto;     
  
  new.caracteristica := vprodutos.caracteristica;
  new.preco := vprodutos.preco;
  new.codigopromocao := vprodutos.promocao;
  new.descricaopromocao := vprodutos.descricaopromocao;
  
  -- Alguns clientes recebem nota fiscal de compra no dep�sito e transferem tudo para as lojas, referenciando a nota de compra.
  -- Quando � necessario fazer uma devolu��o para fornecedor o sistema entende que a nota de entrada j� foi referenciada em uma nota de saida
  -- Ent�o quando o dadofiscal for de transferencia e a notaspag referenciada for de compra, botamos null em codigonota.
  IF NEW.codigonota IS NOT NULL THEN
	IF ehnotafiscalsaidatransferencia(NEW.codigofiscal) AND ehnotafiscalentradacompra((select codigofiscal from notaspag where codigo=NEW.codigonota)) THEN
		NEW.codigonota:=NULL;
	END IF;
  END IF;
  
  
   
  RETURN NEW;

END;
$function$

CREATE OR REPLACE FUNCTION public.produtosdadosfiscais_depoisinseriratualizarapagar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
 vqtdepc   NUMERIC (11,3);
 vqtdepdf  NUMERIC (11,3);
 vcontrato CHAR(20);

 begin
   IF (TG_OP = 'INSERT')  THEN
     SELECT df.contrato into vcontrato
     FROM dadosfiscais df
     WHERE df.numero = NEW.dadofiscal 
       and not coalesce(ehnotafiscalsaidasimplesfaturamento(df.codigofiscal),false);

     IF vcontrato IS NOT NULL THEN
     
       SELECT sum(pc.quantidade - coalesce(pc.cancelado,0)) INTO vqtdepc
       FROM produtoscontratos pc
       WHERE (pc.contrato = vcontrato);

       SELECT sum(pdf.quantidade) INTO vqtdepdf
       FROM produtosdadosfiscais pdf, dadosfiscais df1
       WHERE (df1.contrato = vcontrato) and
             (pdf.dadofiscal = df1.numero) and                          
             (df1.situacao = 'N') and
             (not coalesce(ehnotafiscalsaidasimplesfaturamento(df1.codigofiscal),false));

       IF (vqtdepdf < vqtdepc) THEN
         UPDATE contratos SET situacao = 'P' WHERE (numero = vcontrato) and situacao <> 'P';
       ELSE
         UPDATE contratos SET situacao = 'N' WHERE (numero = vcontrato) and situacao <> 'N';
       END IF;
     END IF;
   END IF;
   
   IF (TG_OP = 'DELETE') or (TG_OP = 'UPDATE') THEN
	
	   IF (TG_OP = 'DELETE') or ((TG_OP = 'UPDATE') and ( (old.produto <> new.produto) or
								   (old.dadofiscal <> new.dadofiscal))) THEN  
		 delete from produtosconferencia
		 where tipo = 'NFS'
		   and codigo = cast(old.dadofiscal as varchar)
		   and produto = old.produto;
	   END IF;
   END IF;
   
   IF (TG_OP ='DELETE') THEN
	RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
 end;
$function$

CREATE OR REPLACE FUNCTION public.romaneios_antesinseriratualizar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  vDataHoraGravacao TimeStamp;
BEGIN
   vDataHoraGravacao:= (SELECT rn.DataHoraGravacao 
                           FROM romaneios rn
                           WHERE rn.numero = NEW.numero);
  
   IF FOUND
   THEN IF vDataHoraGravacao > OLD.DataHoraGravacao
        THEN RAISE EXCEPTION 'As informa�es alteradas ser�o descartadas, pois os dados j� foram atualizados por outro usu�rio.';
        END IF;  
   END IF;
  
   IF NEW.DataHoraGravacao IS NULL
   THEN IF TG_OP = 'INSERT'
        THEN NEW.DataHoraGravacao:=  CAST (TimeOfDay() AS TIMESTAMP WITHOUT TIME ZONE); 
        
	     ELSE IF TG_OP = 'UPDATE'
             THEN IF NEW.DataHoraGravacao = OLD.DataHoraGravacao
                  THEN NEW.DataHoraGravacao:=  CAST (TimeOfDay() AS TIMESTAMP WITHOUT TIME ZONE); 
                  END IF;
             END IF;
        END IF;  
   END IF;
  
  RETURN NEW;
end;
$function$

